import {mountLab,LABS} from './labs.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='ec2k2-study-v2',letters='ABCDE';let D,lessons,questions,byId,store,storageOK=true,timer,toastTimer;
const emptyStore=()=>({version:2,answers:{},bookmarks:[],understood:[],session:null});
try{store=JSON.parse(localStorage.getItem(KEY))||emptyStore();if(store.version!==2||!store.answers||!Array.isArray(store.bookmarks)||!Array.isArray(store.understood))store=emptyStore()}catch{store=emptyStore();storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(store))}catch{storageOK=false;$('#save-status').textContent='Storage unavailable · export to keep progress'}}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
const lessonBy=id=>lessons.find(l=>l.id===id);const answered=()=>questions.filter(q=>store.answers[q.id]);const correct=()=>answered().filter(q=>store.answers[q.id].correct);const stats=()=>`<div class="stats-row"><div class="stat"><strong>${answered().length}<small class="small"> / 400</small></strong><span>QUESTIONS ATTEMPTED</span></div><div class="stat"><strong>${answered().length?Math.round(correct().length/answered().length*100):0}%</strong><span>LATEST ANSWER ACCURACY</span></div><div class="stat"><strong>${store.understood.length}<small class="small"> / ${lessons.reduce((s,l)=>s+l.concepts.length,0)}</small></strong><span>CONCEPTS SELF-CHECKED</span></div><div class="stat"><strong>${answered().length-correct().length}</strong><span>QUESTIONS TO REVISIT</span></div></div>`;
function heroArt(){return `<div class="hero-art"><svg viewBox="0 0 440 310" aria-label="Illustration of two intersecting economic curves"><defs><pattern id="grid" width="31" height="31" patternUnits="userSpaceOnUse"><path d="M31 0H0V31" fill="none" stroke="#dce4cc" stroke-width=".7"/></pattern></defs><rect width="440" height="310" fill="url(#grid)"/><path d="M57 40V248H395" fill="none" stroke="#7b9671"/><path d="M77 76L370 222" fill="none" stroke="#8a6eb1" stroke-width="3"/><path d="M82 223L367 72" fill="none" stroke="#6d99bb" stroke-width="3"/><path d="M222 42V248" stroke="#83a36c" stroke-dasharray="6 5" stroke-width="2"/><circle cx="222" cy="148" r="17" fill="#d9edaa"/><circle cx="222" cy="148" r="5" fill="#35533a"/><text x="365" y="244" font-family="serif" font-style="italic" fill="#8a6eb1">IS</text><text x="372" y="68" font-family="serif" font-style="italic" fill="#6d99bb">LM</text><text x="230" y="51" font-family="serif" fill="#83a36c">FE</text><text x="46" y="31" font-family="serif" font-style="italic" fill="#58734d">r</text><text x="401" y="252" font-family="serif" font-style="italic" fill="#58734d">Y</text><rect x="260" y="105" width="135" height="34" rx="7" fill="#fff" stroke="#dbe4d0"/><text x="274" y="126" font-size="11" font-family="sans-serif" fill="#6a825e">Every line has a reason.</text></svg><div class="hero-note">Change an assumption. Follow the consequences.</div></div>`}
function home(){return `<section class="hero"><div><p class="eyebrow">YOUR EC2102 STUDY SPACE</p><h1>Understand what<br>moves the <em>economy.</em></h1><p class="intro">Build intuition, work through the logic, then put it to the test. The entire supplied lecture sequence, connected in one place.</p><div class="actions"><a href="#decoded" class="primary">Explore Decoded <span>↗</span></a><a href="#ib400" class="secondary">Practise with IB400 <span>→</span></a></div></div>${heroArt()}</section>${stats()}<div class="section-head"><h2>Two ways in. One connected course.</h2><p>Learn the mechanism, then test it.</p></div><div class="path-grid"><a href="#ib400" class="path-card"><span class="tag">PRACTISE & DIAGNOSE</span><span class="card-number">01</span><h2>IB400</h2><p>400 original questions. Five choices each. From tutorial foundations to exam reasoning and challenging edge cases.</p><div class="tagline"><span class="tag">All choices explained</span><span class="tag">Mistake review</span><span class="tag">Exam mode</span></div><strong class="inline-link">Find out what you really understand ↗</strong></a><a href="#decoded" class="path-card"><span class="tag">EXPLORE & UNDERSTAND</span><span class="card-number">02</span><h2>EC2102 Decoded</h2><p>12 connected chapters. Interactive experiments, algebra, positive and negative cases, and the assumptions behind each conclusion.</p><div class="tagline"><span class="tag">${Object.values(LABS).flat().length} experiments</span><span class="tag">${lessons.reduce((s,l)=>s+l.concepts.length,0)} concepts</span><span class="tag">Source references</span></div><strong class="inline-link">Make every curve mean something ↗</strong></a></div><div class="note">Your existing IS–LM–FE and AD–AS policy lab now lives in <a class="inline-link" href="#decoded/islm">Decoded’s IS–LM–FE chapter</a>. This expanded EC2K2 replaces the former homepage.</div>`}
function lessonCards(list=lessons){return list.map(l=>{const i=lessons.indexOf(l),done=l.concepts.filter(c=>store.understood.includes(c.id)).length,n=questions.filter(q=>q.lesson===l.id).length;return `<a class="lesson-card" href="#decoded/${l.id}"><span class="index">${String(i+1).padStart(2,'0')} / DECODED</span><h3>${E(l.title)}</h3><p>${E(l.subtitle)}</p><div class="lesson-card-bottom"><span>${l.concepts.length} concepts · ${n} questions</span><span>${done} / ${l.concepts.length} checked ↗</span></div><div class="bar"><i style="width:${done/l.concepts.length*100}%"></i></div></a>`}).join('')}
function decoded(){return `<p class="eyebrow">EC2102 DECODED</p><h1>From assumptions<br>to understanding.</h1><p class="intro">Work through the mechanism, move the variables yourself, and explain why the result changes. Every concept has separate increase, decrease and boundary cases.</p><div class="note">Lecture Topics 1–9, all three Goods Market decks, initial wealth and growth-rate supplements, plus the two-period consumer–worker tutorial. <a class="inline-link" href="#coverage">See the source coverage map ↗</a></div><div class="search-row"><input id="lesson-search" type="search" placeholder="Find a concept, equation or chapter…" aria-label="Search Decoded"></div><div class="section-head"><h2>The course, connected</h2><p>${lessons.reduce((s,l)=>s+l.concepts.length,0)} concept explanations · ${Object.values(LABS).flat().length} experiments</p></div><div class="course-grid" id="course-grid">${lessonCards()}</div>`}
function bindDecoded(){$('#lesson-search').addEventListener('input',e=>{const s=e.target.value.toLowerCase();$('#course-grid').innerHTML=lessonCards(lessons.filter(l=>JSON.stringify(l).toLowerCase().includes(s)))||'<p class="small">No matching concepts.</p>'})}
function lesson(id,concept){const l=lessonBy(id);if(!l)return decoded();const c=l.concepts.find(c=>c.id===concept)||l.concepts[0],index=l.concepts.indexOf(c),done=store.understood.includes(c.id);return `<a href="#decoded" class="breadcrumb-back">← All chapters</a><div class="lesson-heading"><div><p class="eyebrow">CHAPTER ${String(lessons.indexOf(l)+1).padStart(2,'0')} · EC2102 DECODED</p><h1>${E(l.title)}</h1><p class="intro">${E(l.subtitle)}</p></div><a href="#ib400/${l.id}" class="primary">Practise this chapter ↗</a></div><div class="lesson-layout"><nav class="concept-nav" aria-label="Concepts in this chapter">${l.concepts.map((x,i)=>`<button data-concept="${x.id}" class="${x===c?'active':''}"><b class="${store.understood.includes(x.id)?'done':''}">${store.understood.includes(x.id)?'✓':String(i+1).padStart(2,'0')}</b>${E(x.title)}</button>`).join('')}</nav><div class="concept-body"><article class="concept-panel"><p class="eyebrow">CONCEPT ${index+1} OF ${l.concepts.length}</p><h2>${E(c.title)}</h2><p class="explain">${E(c.explain)}</p>${c.formula?`<div class="formula">${E(c.formula)}</div>`:''}<h3>The mechanism</h3><ol class="mechanism">${c.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="cases"><div class="case"><strong>↑ The increase case</strong>${E(c.increase)}</div><div class="case down"><strong>↓ The decrease case</strong>${E(c.decrease)}</div></div><div class="edge"><h4>When the usual conclusion changes</h4>${E(c.edge)}</div><div class="example"><p class="eyebrow">WORK IT THROUGH</p>${E(c.example)}</div><div class="check"><p class="eyebrow">EXPLAIN IT WITHOUT LOOKING</p><p>${E(c.check.prompt)}</p><details><summary>Compare your explanation</summary><p>${E(c.check.answer)}</p></details></div><p class="source-inline">${l.source.map(s=>`${E(s.file)} · PDF pp ${E(s.pages)}`).join('<br>')}</p></article><div class="concept-actions"><button class="secondary mark-button ${done?'done':''}" id="mark-concept">${done?'✓ Self-checked':'I can explain this'}</button><a class="secondary" href="#ib400/${l.id}/${c.id}">Test this concept ↗</a>${index<l.concepts.length-1?`<a class="primary" href="#decoded/${l.id}/${l.concepts[index+1].id}">Next concept →</a>`:`<a class="primary" href="#decoded">All chapters →</a>`}</div><section class="lab-panel" id="chapter-lab"></section></div></div>`}
function bindLesson(id,concept){const l=lessonBy(id);if(!l){bindDecoded();return}const c=l.concepts.find(c=>c.id===concept)||l.concepts[0];document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>location.hash=`decoded/${l.id}/${b.dataset.concept}`);$('#mark-concept').onclick=()=>{const n=store.understood.indexOf(c.id);if(n<0)store.understood.push(c.id);else store.understood.splice(n,1);save();const el=$('#mark-concept');el.classList.toggle('done',n<0);el.textContent=n<0?'✓ Self-checked':'I can explain this';document.querySelector(`[data-concept="${c.id}"] b`).textContent=n<0?'✓':String(l.concepts.indexOf(c)+1).padStart(2,'0');toast(n<0?'Concept self-check saved':'Concept returned to your study list')};mountLab($('#chapter-lab'),id)}
let filters={lesson:'all',difficulty:'all',status:'all',search:'',concept:''};
function filtered(){return questions.filter(q=>(filters.lesson==='all'||q.lesson===filters.lesson)&&(filters.difficulty==='all'||q.difficulty===filters.difficulty)&&(!filters.concept||q.concept===filters.concept)&&(!filters.search||[q.prompt,...q.choices.map(c=>c.text),lessonBy(q.lesson)?.title].join(' ').toLowerCase().includes(filters.search.toLowerCase()))&&(filters.status==='all'||filters.status==='new'&&!store.answers[q.id]||filters.status==='wrong'&&store.answers[q.id]&&!store.answers[q.id].correct||filters.status==='bookmarked'&&store.bookmarks.includes(q.id)||filters.status==='uncertain'&&store.answers[q.id]&&store.answers[q.id].confidence!=='confident'))}
function quizLobby(lid,cid){filters={lesson:lessonBy(lid)?lid:'all',difficulty:'all',status:'all',search:'',concept:cid||''};return `<p class="eyebrow">IB400 · THE QUESTION BANK</p><h1>Know why your<br>answer is right.</h1><p class="intro">400 original MCQs with five choices each. Practise the mechanism, identify tempting mistakes, and return to the exact concept when you need it.</p>${stats()}<div class="filter-panel"><label>Chapter<select id="filter-lesson"><option value="all">All 12 chapters</option>${lessons.map(l=>`<option value="${l.id}" ${filters.lesson===l.id?'selected':''}>${E(l.title)}</option>`).join('')}</select></label><label>Difficulty<select id="filter-difficulty"><option value="all">All difficulties</option><option>Tutorial</option><option>Exam</option><option>Challenge</option></select></label><label>Review queue<select id="filter-status"><option value="all">All questions</option><option value="new">Unattempted</option><option value="wrong">Last answer incorrect</option><option value="bookmarked">Bookmarked</option><option value="uncertain">Unsure or guessed</option></select></label><label>Search<input id="filter-search" type="search" placeholder="Keyword, idea or equation…"></label></div>${cid?`<div class="note">Focused on ${E(lessonBy(lid)?.concepts.find(c=>c.id===cid)?.title||cid)}. <button class="inline-link" id="clear-concept">Show all chapter concepts</button></div>`:''}<div class="session-options"><span id="pool-count">${filtered().length} matching questions</span><select id="session-mode" aria-label="Practice or exam mode"><option value="practice">Practice · immediate explanations</option><option value="exam">Exam · explanations after finishing</option></select><select id="session-count" aria-label="Number of questions"><option value="10">10 questions</option><option value="20" selected>20 questions</option><option value="40">40 questions</option><option value="100">100 questions</option><option value="400">All matching questions</option></select><select id="session-minutes" aria-label="Session timer"><option value="0">Untimed</option><option value="30">30 minutes</option><option value="60">60 minutes</option><option value="120">120 minutes</option></select><button class="primary" id="start-session">Start a new set →</button></div>${store.session?`<div class="note"><strong>Saved ${store.session.mode} session</strong> · ${Object.keys(store.session.responses).length} / ${store.session.ids.length} answered. <a class="inline-link" href="#session">${store.session.finished?'Review results':'Continue session'} ↗</a></div>`:''}<div class="note">Tutorial checks build the foundations. Exam questions combine steps and model assumptions. Challenge questions test limits, edge cases and competing mechanisms. These are original study questions, not official exam questions. Starting a new set replaces the active session but keeps your answer history and bookmarks.</div><div class="section-head"><h2>Your course coverage</h2><p>Each question links back to Decoded.</p></div><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Chapter</th><th>Questions</th><th>Attempted</th><th>Latest correct</th><th></th></tr></thead><tbody>${lessons.map(l=>{const qs=questions.filter(q=>q.lesson===l.id),attempt=qs.filter(q=>store.answers[q.id]);return `<tr><td>${E(l.title)}</td><td>${qs.length}</td><td>${attempt.length}</td><td>${attempt.filter(q=>store.answers[q.id].correct).length}</td><td><a class="inline-link" href="#ib400/${l.id}">Practise ↗</a></td></tr>`}).join('')}</tbody></table></div>`}
function bindLobby(){for(const k of ['lesson','difficulty','status','search'])$('#filter-'+k).addEventListener(k==='search'?'input':'change',e=>{filters[k]=e.target.value;if(k==='lesson')filters.concept='';$('#pool-count').textContent=filtered().length+' matching questions';$('#start-session').disabled=filtered().length===0});$('#clear-concept')?.addEventListener('click',()=>{filters.concept='';$('#clear-concept').parentElement.remove();$('#pool-count').textContent=filtered().length+' matching questions'});$('#start-session').onclick=()=>{const ids=filtered().map(q=>q.id);if(!ids.length)return toast('No matching questions');for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}const limit=Number($('#session-count').value),minutes=Number($('#session-minutes').value);store.session={ids:ids.slice(0,limit),mode:$('#session-mode').value,index:0,responses:{},confidence:{},finished:false,started:Date.now(),end:minutes?Date.now()+minutes*60000:null};save();location.hash='session'}}
function record(q,choice,confidence){const old=store.answers[q.id];store.answers[q.id]={choice,correct:choice===q.answer,confidence:confidence||'unsure',attempts:(old?.attempts||0)+1,firstCorrect:old?.firstCorrect??choice===q.answer,time:Date.now()};}
function finish(){const s=store.session;if(!s||s.finished)return;s.finished=true;s.ended=Date.now();for(const id of s.ids){const q=byId[id],r=s.responses[id];if(r!==undefined&&s.mode==='exam')record(q,r,s.confidence[id]);}save();render()}
function sessionView(){const s=store.session;if(!s)return `<div class="empty"><h2>Start a practice set</h2><p>Choose your topic, difficulty and session length.</p><a href="#ib400" class="primary">Open IB400 →</a></div>`;if(s.finished&&!s.review)return results();s.index=Math.max(0,Math.min(s.ids.length-1,s.index||0));const q=byId[s.ids[s.index]];if(!q)return '<div class="empty">The saved question is unavailable. Start a new session.</div>';const choice=s.responses[q.id],reveal=s.mode==='practice'&&choice!==undefined||s.finished,ok=choice===q.answer;return `<a class="breadcrumb-back" href="#ib400">← Question bank</a><div class="section-head" style="margin-top:0"><div><p class="eyebrow">IB400 · ${s.finished?'REVIEW':s.mode.toUpperCase()}</p><h2>${s.finished?'Review the reasoning.':'One question. Five possibilities.'}</h2></div><span class="tag" id="session-timer">${s.end&&!s.finished?'Timer running':'Untimed'}</span></div><div class="quiz-layout"><article class="question-card"><div class="question-meta"><span class="question-id">QUESTION ${s.index+1} / ${s.ids.length} · #${String(q.id).padStart(3,'0')}</span><span class="badge ${q.difficulty}">${q.difficulty}</span><button class="bookmark ${store.bookmarks.includes(q.id)?'active':''}" id="bookmark" aria-label="${store.bookmarks.includes(q.id)?'Remove bookmark':'Bookmark question'}">${store.bookmarks.includes(q.id)?'★':'☆'}</button></div><p class="eyebrow">${E(lessonBy(q.lesson)?.title)}</p><h2>${E(q.prompt)}</h2><div class="choices">${q.choices.map((c,i)=>`<button class="choice ${choice===i?'selected ':''}${reveal?(i===q.answer?'correct':i===choice?'wrong':''):''}" data-choice="${i}" ${reveal?'disabled':''}><span class="letter">${letters[i]}</span><span>${E(c.text)}${reveal?`<div class="choice-feedback">${E(c.feedback)}</div>`:''}</span></button>`).join('')}</div>${!s.finished?`<div class="confidence"><span>How certain are you?</span>${['guessed','unsure','confident'].map(c=>`<button data-confidence="${c}" class="${s.confidence[q.id]===c?'active':''}">${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div>`:''}${reveal?`<div class="feedback ${ok?'':'incorrect'}"><h3>${choice===undefined?'Unanswered':ok?'Correct. Now check the mechanism.':'Revisit the mechanism.'} <span class="small">Answer ${letters[q.answer]}</span></h3><p>${E(q.explanation)}</p><a class="inline-link" href="#decoded/${q.lesson}/${q.concept}">Understand this in Decoded ↗</a><p class="source-inline">${E(q.source)}</p></div>`:s.mode==='exam'?'<p class="small">Your selection is saved. Answers and explanations appear after finishing.</p>':''}<div class="question-actions"><button class="secondary" id="prev-question" ${s.index===0?'disabled':''}>← Previous</button><div class="group">${s.mode==='practice'&&!reveal?'<button class="primary" id="check-answer" disabled>Check answer</button>':''}<button class="${reveal||s.mode==='exam'?'primary':'secondary'}" id="next-question">${s.index===s.ids.length-1?'Finish & review':'Next →'}</button></div></div></article><aside class="question-aside"><div class="session-box"><h3>${Object.keys(s.responses).length} of ${s.ids.length} answered</h3><p>Green means correct. Peach means revisit. Exam answers stay hidden until you finish.</p><div class="question-map">${s.ids.map((id,i)=>{const r=s.responses[id],show=s.finished||s.mode==='practice';return `<button data-index="${i}" class="${i===s.index?'active ':''}${r!==undefined?(show?(r===byId[id].answer?'right':'wrong'):'pending'):''}" aria-label="Go to question ${i+1}">${i+1}</button>`}).join('')}</div><button class="quiet" id="finish-session">${s.finished?'Back to results':'Finish this set'}</button></div><p class="small" style="margin-top:15px">Progress is stored in this browser. Use Export progress to keep a backup or transfer devices.</p></aside></div>`}
function bindSession(){const s=store.session;if(!s)return;if(s.finished&&!s.review){bindResults();return}const q=byId[s.ids[s.index]];let selected=s.responses[q.id];document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.choice);if(s.mode==='exam'){s.responses[q.id]=selected;save()}document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));if($('#check-answer'))$('#check-answer').disabled=false});document.querySelectorAll('[data-confidence]').forEach(b=>b.onclick=()=>{s.confidence[q.id]=b.dataset.confidence;if(s.mode==='practice'&&store.answers[q.id])store.answers[q.id].confidence=b.dataset.confidence;save();document.querySelectorAll('[data-confidence]').forEach(x=>x.classList.toggle('active',x===b))});$('#check-answer')?.addEventListener('click',()=>{if(selected===undefined)return;s.responses[q.id]=selected;record(q,selected,s.confidence[q.id]);save();render(false)});$('#bookmark').onclick=()=>{const n=store.bookmarks.indexOf(q.id);if(n<0)store.bookmarks.push(q.id);else store.bookmarks.splice(n,1);save();$('#bookmark').textContent=n<0?'★':'☆';$('#bookmark').classList.toggle('active',n<0);$('#bookmark').setAttribute('aria-label',n<0?'Remove bookmark':'Bookmark question')};$('#prev-question').onclick=()=>{s.index--;save();render(false)};$('#next-question').onclick=()=>{if(s.index<s.ids.length-1){s.index++;save();render(false)}else if(s.finished){s.review=false;save();render()}else finish()};$('#finish-session').onclick=()=>{if(s.finished){s.review=false;save();render()}else finish()};document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{s.index=Number(b.dataset.index);save();render(false)});if(s.end&&!s.finished){const tick=()=>{const remaining=Math.max(0,Math.ceil((s.end-Date.now())/1000));if($('#session-timer'))$('#session-timer').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} remaining`;if(!remaining){clearInterval(timer);finish();toast('Time is up. Your saved answers have been marked.')}};tick();timer=setInterval(tick,1000)}}
function results(){const s=store.session,n=s.ids.filter(id=>s.responses[id]===byId[id].answer).length;return `<p class="eyebrow">IB400 · SESSION RESULTS</p><h1>Turn the mistakes<br>into understanding.</h1><div class="result-score">${n} <span class="small">/ ${s.ids.length} correct</span></div><p class="intro">${Object.keys(s.responses).length} answered · ${s.ids.length-Object.keys(s.responses).length} unanswered · ${Math.round(n/s.ids.length*100)}% across the full set.</p><div class="actions"><button class="primary" id="review-all">Review every answer →</button><button class="secondary" id="retry-wrong">Retry incorrect & unanswered</button><a class="secondary" href="#ib400">Choose another set</a></div><div class="section-head"><h2>Your answer trail</h2><p>Open any question to inspect all five explanations.</p></div><div class="review-list">${s.ids.map((id,i)=>{const q=byId[id],r=s.responses[id];return `<button class="review-item" data-review="${i}"><strong>${r===q.answer?'✓':r===undefined?'○':'×'} #${id}</strong><span>${E(q.prompt)}<br><span class="small">${r===undefined?'Unanswered':`Your answer ${letters[r]}`} · Correct ${letters[q.answer]} · ${E(q.difficulty)}</span></span></button>`}).join('')}</div>`}
function bindResults(){const s=store.session;$('#review-all').onclick=()=>{s.review=true;s.index=0;save();render()};document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{s.review=true;s.index=Number(b.dataset.review);save();render()});$('#retry-wrong').onclick=()=>{const ids=s.ids.filter(id=>s.responses[id]!==byId[id].answer);if(!ids.length)return toast('Every question in this set is correct');store.session={ids,mode:'practice',index:0,responses:{},confidence:{},finished:false,started:Date.now(),end:null};save();render()}}
function coverage(){return `<p class="eyebrow">COURSE MAP & SOURCES</p><h1>Know what is covered.<br>Know what is assumed.</h1><p class="intro">The study bank and Decoded follow the supplied EC2102 lecture decks and tutorials. Source references use PDF page numbers.</p><div class="note"><strong>Coverage boundary</strong> · The local set contains 13 lecture decks and tutorials 1–9. The course introduction mentions 10 tutorials and says final format and coverage will be announced in Week 13. A separate final coverage announcement and Tutorial 10 were not available in the source set. This is comprehensive coverage of the supplied topics, not certification that no later course material exists.</div><div class="coverage-section"><h2>How to use the three levels</h2><p>Tutorial questions test direct definitions, formulas and single mechanisms. Exam questions combine calculations, curves and assumptions. Challenge questions test counterexamples, limiting cases and model comparisons. These difficulty labels are study-design judgments, not official NUS classifications. The bank is original and is not a prediction of exam questions or format.</p><p>The concept checks and “I can explain this” markers are self-assessments, not proof of mastery. Use the mistake queue and try explaining each answer without the notes.</p></div><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Chapter</th><th>Concepts</th><th>Tutorial</th><th>Exam</th><th>Challenge</th><th>Total</th></tr></thead><tbody>${lessons.map(l=>{const q=questions.filter(q=>q.lesson===l.id);return `<tr><td><a href="#decoded/${l.id}">${E(l.title)} ↗</a></td><td>${l.concepts.length}</td>${['Tutorial','Exam','Challenge'].map(d=>`<td>${q.filter(q=>q.difficulty===d).length}</td>`).join('')}<td>${q.length}</td></tr>`}).join('')}<tr><th>Total</th><th>${lessons.reduce((s,l)=>s+l.concepts.length,0)}</th>${['Tutorial','Exam','Challenge'].map(d=>`<th>${questions.filter(q=>q.difficulty===d).length}</th>`).join('')}<th>${questions.length}</th></tr></tbody></table></div><div class="coverage-section"><h2>Source and concept index</h2><p>Explanations and questions are original paraphrases grounded in the course material. Original lecture PDFs and recordings are not redistributed. Model equations in the experiments use transparent teaching calibrations.</p>${lessons.map(l=>`<article class="source-card"><h3>${E(l.title)}</h3>${l.source.map(s=>`<p>${E(s.file)} · PDF pp ${E(s.pages)}</p>`).join('')}<div class="coverage-concepts">${l.concepts.map(c=>`<a href="#decoded/${l.id}/${c.id}">${E(c.title)} · ${questions.filter(q=>q.concept===c.id).length} MCQs</a>`).join('')}</div></article>`).join('')}</div><div class="coverage-section"><h2>Model boundaries that matter</h2><p>Individual labour supply and saving responses can be ambiguous. Aggregate slopes are maintained assumptions. The fixed-price Keynesian fiscal lab holds FE fixed; the Classical fiscal lesson allows the wealth effect to shift labour supply and FE. Horizontal fixed-price SRAS and upward-sloping misperceptions SRAS are different models. The liquidity-trap floor is on the nominal rate, not the real rate. Hysteresis changes the fixed-natural-rate benchmark.</p><p>The simulations use illustrative parameters. They do not estimate the economy or forecast adjustment time. Long-run growth and open-economy models are excluded because the course introduction assigns them to EC3102.</p></div><div class="note">Study progress stays in this browser. Export and import are available in the top bar. Website access remains private to the owner. Independent study aid, not an official NUS resource.</div>`}
function render(scroll=true){clearInterval(timer);let [page,id,cid]=(location.hash.slice(1)||'home').split('/');if(page==='lab'||page==='guide'||page==='sources'||page==='quiz'){location.replace(page==='quiz'?'#ib400':page==='sources'?'#coverage':'#decoded/islm');return}if(page==='question'&&byId[Number(id)]){store.session={ids:[Number(id)],mode:'practice',index:0,responses:{},confidence:{},finished:false,started:Date.now(),end:null};save();location.replace('#session');return}const titles={home:'Your study space',ib400:'IB400',decoded:'EC2102 Decoded',session:'IB400',coverage:'Course map & sources'};$('#breadcrumb').textContent=titles[page]||titles.home;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='session'?'ib400':page)));$('#main').innerHTML=page==='decoded'?(id?lesson(id,cid):decoded()):page==='ib400'?quizLobby(id,cid):page==='session'?sessionView():page==='coverage'?coverage():home();if(page==='decoded')id?bindLesson(id,cid):bindDecoded();if(page==='ib400')bindLobby();if(page==='session')bindSession();if(scroll)window.scrollTo({top:0,behavior:'instant'});document.title=`EC2K2 · ${titles[page]||'Understand the economy'}`;}
$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({...store,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EC2K2-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded')};
$('#import-progress').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup is too large');const x=JSON.parse(await file.text());if(x.version!==2||typeof x.answers!=='object'||!Array.isArray(x.bookmarks)||!Array.isArray(x.understood))throw Error('Not an EC2K2 progress backup');const clean=emptyStore();for(const[id,a]of Object.entries(x.answers)){if(byId[id]&&Number.isInteger(a.choice)&&a.choice>=0&&a.choice<5)clean.answers[id]={choice:a.choice,correct:a.choice===byId[id].answer,confidence:['guessed','unsure','confident'].includes(a.confidence)?a.confidence:'unsure',attempts:Math.max(1,Number(a.attempts)||1),firstCorrect:!!a.firstCorrect,time:Number(a.time)||Date.now()}}clean.bookmarks=x.bookmarks.filter(id=>byId[id]);const concepts=new Set(lessons.flatMap(l=>l.concepts.map(c=>c.id)));clean.understood=[...new Set(x.understood.filter(id=>concepts.has(id)))];if(x.session&&Array.isArray(x.session.ids)&&x.session.ids.length&&x.session.ids.every(id=>byId[id])&&['practice','exam'].includes(x.session.mode)&&x.session.responses&&typeof x.session.responses==='object'){const s=x.session,ids=[...new Set(s.ids)],responses={};for(const[id,r]of Object.entries(s.responses))if(ids.includes(Number(id))&&Number.isInteger(r)&&r>=0&&r<5)responses[id]=r;clean.session={ids,mode:s.mode,index:Math.max(0,Math.min(ids.length-1,Number(s.index)||0)),responses,confidence:s.confidence&&typeof s.confidence==='object'?s.confidence:{},finished:!!s.finished,review:!!s.review,started:Number(s.started)||Date.now(),end:Number(s.end)>0?Number(s.end):null}}store=clean;save();render(false);toast('Study progress imported')}catch(err){toast('Import failed. '+err.message)}finally{e.target.value=''}};
try{const res=await fetch('data.json?v=2');if(!res.ok)throw Error('Course content could not be loaded');D=await res.json();lessons=D.lessons;questions=D.questions;byId=Object.fromEntries(questions.map(q=>[q.id,q]));if(!Array.isArray(lessons)||!Array.isArray(questions))throw Error('Course data format is invalid');if(!storageOK)$('#save-status').textContent='Storage unavailable · use Export';window.addEventListener('hashchange',()=>render());render()}catch(err){$('#main').innerHTML=`<div class="empty"><h1>Unable to load the course</h1><p>${E(err.message)}</p><button class="primary" onclick="location.reload()">Try again</button></div>`;console.error(err)}
